SET @prov_c := '%s';
SET @id:= '%s';
SET @cat_id := '%s';
SET @send :=  IF((SELECT active FROM sys_report WHERE cat_id = @cat_id and id = @id )=1,0,2);
SET @b_year:=(SELECT yearprocess FROM pk_byear LIMIT 1);
SET	@start_d:=concat(@b_year-1,'1001');
SET @end_d:=concat(@b_year,'0930');

CREATE TABLE IF NOT EXISTS s_cigarette15(
 id varchar(32) NOT NULL,
  hospcode varchar(5) NOT NULL,
  areacode varchar(8) NOT NULL,
  flag_sent varchar(1) DEFAULT NULL,
  date_com varchar(14) DEFAULT NULL,
  b_year varchar(4) NOT NULL,
  target int(7) DEFAULT 0,
  result int(7) DEFAULT 0,
	PRIMARY KEY (id,hospcode,areacode,b_year),
	KEY (hospcode),
	KEY (areacode),
	KEY (b_year)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

DELETE FROM s_cigarette15 WHERE id=@id AND b_year=(@b_year+543);

INSERT IGNORE INTO s_cigarette15 
(
SELECT
@id,p.check_hosp hospcode,p.check_vhid as areacode
,@send,DATE_FORMAT(now(),'%Y%m%d%H%i') as d_com,@b_year+543
,COUNT(DISTINCT p.cid) target
,COUNT(DISTINCT IF(s.cid IS NOT NULL ,s.cid,NULL)) result
FROM
t_person_cid p 
LEFT JOIN t_cigarette s ON p.cid=s.CID AND s.c_code NOT IN('1B51','1B52')
WHERE p.age_y BETWEEN 15  AND 70 AND p.check_typearea IN(1,3) 
AND  p.DISCHARGE IN(9) AND p.NATION IN(99) AND LENGTH(p.cid) =13
AND substr(p.check_vhid,1,2) IN(@prov_c)
GROUP BY p.check_hosp,p.check_vhid
);
